Here is the Python function implementing this logic:

```python
def transform(grid):
    if not grid or not grid[0]:
        return grid
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                continue
            # If it's 3, check if 3x3 block is all 3s (within valid grid indices)
            is_block_all_3s = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    nr, nc = r + dr, c + dc
                    # Clamp to grid boundaries
                    if nr < 0 or nr >= rows: nr = 0 if nr < 0 else rows - 1
                    if nc < 0 or nc >= cols: nc = 0 if nc < 0 else cols - 1

                    if grid[nr][nc] != 3:
                        is_block_all_3s = False
                        break
                if not is_block_all_3s:
                    break

            if not is_block_all_3s:
                result[r][c] = 1

    return result
